from collections import deque

def can_finish(n: int, prereqs: list[list[int]]) -> bool:
    adj, indeg = [[] for _ in range(n)], [0] * n
    for course, needs in prereqs:
        adj[needs].append(course)
        indeg[course] += 1
    queue = deque(i for i in range(n) if indeg[i] == 0)
    taken = 0
    while queue:
        u = queue.popleft()
        taken += 1
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                queue.append(v)
    return taken == n

