def can_finish(n: int, prereqs: list[list[int]]) -> bool:
    done = [False] * n
    while True:
        blocked = [False] * n
        for course, needs in prereqs:
            if not done[needs]:
                blocked[course] = True
        ready = [c for c in range(n) if not done[c] and not blocked[c]]
        if not ready:
            return all(done)
        for c in ready:
            done[c] = True
